import * as React from 'react';
import { expect, it, vi, afterEach } from 'vitest';
import { render, fireEvent, screen, cleanup, act } from '@testing-library/react';
import { Field } from '@base-ui/react/field';
import { Form } from '@base-ui/react/form';

afterEach(cleanup);

it('S1: reset to empty after typing in onChange mode shows required error', async () => {
  function App() {
    const [value, setValue] = React.useState('');
    return (
      <Field.Root data-testid="root" validationMode="onChange">
        <Field.Control required value={value} onValueChange={setValue} />
        <Field.Error data-testid="error" />
        <button type="button" onClick={() => setValue('')}>reset</button>
      </Field.Root>
    );
  }
  render(<App />);
  const root = screen.getByTestId('root');
  fireEvent.change(screen.getByRole('textbox'), { target: { value: 'abc' } });
  console.log('S1 after typing', root.outerHTML);
  fireEvent.click(screen.getByRole('button'));
  await act(async () => {});
  console.log('S1 after reset', root.outerHTML);
});

it('S1b: form submit ok then reset controlled values (onSubmit mode)', async () => {
  function App() {
    const [value, setValue] = React.useState('');
    return (
      <Form onFormSubmit={() => { setValue(''); }}>
        <Field.Root data-testid="root" name="a">
          <Field.Control required value={value} onValueChange={setValue} />
          <Field.Error data-testid="error" />
        </Field.Root>
        <button type="submit">submit</button>
      </Form>
    );
  }
  render(<App />);
  const root = screen.getByTestId('root');
  fireEvent.change(screen.getByRole('textbox'), { target: { value: 'abc' } });
  fireEvent.click(screen.getByRole('button'));
  await act(async () => {});
  console.log('S1b after submit+reset', root.outerHTML);
});

it('S2: renders per keystroke in onChange mode, controlled', async () => {
  let renders = 0;
  const validate = vi.fn(() => null);
  function App() {
    const [value, setValue] = React.useState('');
    return (
      <Field.Root validationMode="onChange" validate={validate}>
        <Field.Control
          data-testid="control"
          value={value}
          onValueChange={setValue}
          render={(props) => { renders += 1; return <input {...props} />; }}
        />
      </Field.Root>
    );
  }
  render(<App />);
  const control = screen.getByTestId('control');
  fireEvent.change(control, { target: { value: 'a' } });
  const settled = renders;
  fireEvent.change(control, { target: { value: 'ab' } });
  fireEvent.change(control, { target: { value: 'abc' } });
  console.log('S2 controlled renders for 2 keystrokes:', renders - settled);
});

